import { describe, expect, it } from "vitest";
import { THEMES } from "@poly/engine";
import { TOKEN_EMOJI, tokenEmoji, tokenImageUrl } from "../src/ui/token-icons.ts";

const ids = Object.values(THEMES).flatMap((th) => th.tokens.map((tok) => tok.id));
// the thumbnails are generated by `npm run assets:tokens`; vite resolves the glob at transform time
const files = Object.keys(import.meta.glob("../public/assets/tokens/*.webp", { query: "?url" }));

describe("token icons", () => {
  it("covers 32 distinct token ids across the themes", () => {
    expect(new Set(ids).size).toBe(ids.length);
    expect(ids.length).toBe(32);
  });
  it.each(ids)("%s has a thumbnail file", (id) => {
    expect(files).toContain(`../public${tokenImageUrl(id)}`);
  });
  it("has no thumbnail without a token", () => {
    expect(files.length).toBe(ids.length);
  });
  it("has a distinct fallback emoji for every token, none equal to the generic one", () => {
    const emoji = ids.map((id) => tokenEmoji(id));
    expect(new Set(emoji).size).toBe(ids.length);
    expect(emoji).not.toContain(tokenEmoji("no-such-token"));
    expect(Object.keys(TOKEN_EMOJI).sort()).toEqual([...ids].sort());
  });
});
